declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require __DIR__.'/includes/project_manager.php';require_permission('project_tasks.manage');$pdo=db();$id=max(0,(int)($_GET['id']??$_POST['id']??0));$task=null;if($id){$s=$pdo->prepare('SELECT * FROM project_tasks WHERE id=?');$s->execute([$id]);$task=$s->fetch();if(!$task){http_response_code(404);exit('Tarea no encontrada.');}}$projectId=(int)($_GET['project_id']??$_POST['project_id']??($task['project_id']??0));$projects=pm_project_options($pdo);if(!$projectId&&$projects)$projectId=(int)$projects[0]['id'];$project=$projectId?pm_fetch_project($pdo,$projectId):null;$pageTitle=$task?'Editar tarea':'Nueva tarea';$users=$pdo->query('SELECT id,name FROM users WHERE is_active=1 ORDER BY name')->fetchAll();$m=$pdo->prepare('SELECT id,name FROM project_milestones WHERE project_id=? ORDER BY sort_order,due_date,id');$m->execute([$projectId]);$milestones=$m->fetchAll();$parents=$pdo->prepare('SELECT id,title FROM project_tasks WHERE project_id=? AND id<>? ORDER BY title');$parents->execute([$projectId,$id]);$parents=$parents->fetchAll();$errors=[];$v=fn($k,$d='')=>$_POST[$k]??($task[$k]??$d);
