<form method="post" class="panel"><div class="panel-header"><div><h2><?=$task?'Editar tarea':'Nueva tarea'?></h2><span class="table-sub">Planificación tipo Project: responsable, fechas, avance, horas y jerarquía.</span></div><a class="btn btn-light btn-small" href="project_kanban.php?project_id=<?=$projectId?>">Volver al Kanban</a></div><div class="panel-body form-grid"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><label>Proyecto<select name="project_id" required><?php foreach($projects as$p):?><option value="<?=$p['id']?>" <?=$projectId===(int)$p['id']?'selected':''?>><?=e($p['name'])?></option><?php endforeach;?></select></label><label>Hito<select name="milestone_id"><option value="0">Sin hito</option><?php foreach($milestones as$m):?><option value="<?=$m['id']?>" <?=(int)$v('milestone_id')===(int)$m['id']?'selected':''?>><?=e($m['name'])?></option><?php endforeach;?></select></label><label class="full">Título *<input name="title" required value="<?=e($v('title'))?>"></label><label>Responsable<select name="assigned_to"><option value="0">Sin asignar</option><?php foreach($users as$u):?><option value="<?=$u['id']?>" <?=(int)$v('assigned_to')===(int)$u['id']?'selected':''?>><?=e($u['name'])?></option><?php endforeach;?></select></label><label>Subtarea de<select name="parent_task_id"><option value="0">Tarea principal</option><?php foreach($parents as$x):?><option value="<?=$x['id']?>" <?=(int)$v('parent_task_id')===(int)$x['id']?'selected':''?>><?=e($x['title'])?></option><?php endforeach;?></select></label><label>Estado<select name="status"><?php foreach(['backlog','todo','in_progress','review','blocked','done'] as$x):?><option value="<?=$x?>" <?=$v('status','todo')===$x?'selected':''?>><?=e(pm_task_status_label($x))?></option><?php endforeach;?></select></label><label>Prioridad<select name="priority"><?php foreach(['low','normal','high','urgent'] as$x):?><option value="<?=$x?>" <?=$v('priority','normal')===$x?'selected':''?>><?=e(pm_priority_labe